SELECT p.id AS pid, s.id, s.symbol, s.interval_code, s.candle_open_time, s.generated_at, s.signal_mode, s.decision, s.original_decision, s.total_score, s.confidence_score, s.final_entry_allowed, s.primary_blocking_stage, s.latest_price FROM crypto_ai.paper_position p JOIN crypto_ai.trade_signal s ON s.symbol = p.symbol AND ((s.interval_code = '1m' AND s.generated_at BETWEEN p.opened_at - INTERVAL 10 MINUTE AND p.closed_at + INTERVAL 30 SECOND) OR (s.interval_code IN ('5m','1h') AND s.generated_at BETWEEN p.opened_at - INTERVAL 70 MINUTE AND p.closed_at + INTERVAL 30 SECOND)) WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id, s.generated_at LIMIT 600;